"""Build offline HTML views from the hash-verified saved experiment evidence."""
import argparse,difflib,html,json,re
from pathlib import Path

HERE=Path(__file__).resolve().parent
LABELS={
 'baseline':'Before additional CPU edits',
 'delete_fillers':'Filler phrases',
 'delete_articles':'Articles: original implementation',
 'delete_soft_modifiers':'Articles + eight selected adjectives',
 'delete_pos_guarded':'Articles + broad adjectives/adverbs',
 'delete_articles_case_guard':'Articles with identifier/case protection',
 'delete_adjective_adverb_only':'Adjectives/adverbs only',
 'percent_only':'Protected articles + percent notation',
 'numbers_percent':'Numeric notation: original prototype',
 'numbers_percent_guarded':'Protected articles + quantity-only numeric notation',
}
RUNS={'initial':['baseline','delete_fillers','delete_articles','delete_soft_modifiers','delete_pos_guarded'],
      'case_guard':['delete_articles_case_guard'],'modifiers_only':['delete_adjective_adverb_only'],
      'numbers':['percent_only','numbers_percent'],'numbers_guarded':['numbers_percent_guarded']}
CSS='''
:root{--ink:#173932;--muted:#596b64;--paper:#f5f5ed;--line:#d7e1d5;--green:#dcebd8;--orange:#a44127;--gold:#f5e9bb}
*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font:16px/1.65 system-ui,-apple-system,sans-serif}main{max-width:1280px;margin:auto;padding:32px 24px 72px}nav{display:flex;gap:22px;flex-wrap:wrap;font-size:14px;margin-bottom:38px}a{color:#17614d;text-underline-offset:4px}h1{font:clamp(36px,5vw,66px)/1.1 Georgia,serif;max-width:1000px;letter-spacing:-1.4px}h2{font:32px/1.2 Georgia,serif;margin-top:52px}h3{line-height:1.3}.eyebrow{font-size:12px;letter-spacing:2px;font-weight:750;text-transform:uppercase}.lead{max-width:850px;font-size:20px;color:var(--muted)}.cards{display:grid;grid-template-columns:repeat(3,1fr);gap:18px;margin:28px 0}.card,section.panel{background:#fff;border:1px solid var(--line);border-radius:16px;padding:22px}.card b.big{font-size:34px;display:block}.small{font-size:14px;color:var(--muted)}.note{background:var(--gold);padding:18px 22px;border-radius:12px}.scroll{overflow:auto;border:1px solid var(--line);border-radius:14px;background:white}table{width:100%;border-collapse:collapse;min-width:920px}td,th{text-align:left;padding:15px 12px;border-bottom:1px solid var(--line);vertical-align:top}thead th{background:#e8eee1;font-size:13px}tbody th{max-width:310px;font-size:14px}.good{background:#eaf3e5}.risk{color:var(--orange)}.bar{display:inline-block;background:#8aaf89;height:7px;border-radius:7px;margin-top:5px;max-width:170px}.tag{font-size:12px;background:#e7eee1;padding:3px 8px;border-radius:50px;display:inline-block}.two{display:grid;grid-template-columns:1fr 1fr;gap:20px}select,button{font:inherit;padding:11px;border:1px solid #afc2b2;border-radius:9px;background:white;color:var(--ink);max-width:100%}label{display:block;font-weight:650;margin:15px 0 7px}.filters{display:grid;grid-template-columns:2fr 1fr;gap:18px}.summary{background:white;border:1px solid var(--line);border-radius:14px;padding:22px;min-width:0}.summary p{overflow-wrap:anywhere}.summary ul{padding-left:22px}details{border-top:1px solid var(--line);padding:12px 0}summary{cursor:pointer;font-weight:650}pre,code{overflow-wrap:anywhere;white-space:pre-wrap;font-size:13px}del{background:#ffe0d4;text-decoration:line-through}ins{background:#dcefcf;text-decoration:none}dt{font-weight:650;margin-top:10px}dd{margin-left:16px}.pair{background:white;border:1px solid var(--line);border-radius:14px;padding:20px;margin:18px 0}.pair .two>div{overflow-wrap:anywhere}footer{border-top:1px solid var(--line);margin-top:55px;padding-top:20px;color:var(--muted)}@media(max-width:780px){.cards,.two,.filters{grid-template-columns:1fr}main{padding:24px 16px 50px}h1{letter-spacing:-.5px}}'''


def load(p):return json.loads(Path(p).read_text())
def readlines(p):return [json.loads(l) for l in Path(p).read_text().splitlines() if l.strip()]
def dump(value):return json.dumps(value,ensure_ascii=False).replace('<','\\u003c').replace('>','\\u003e').replace('&','\\u0026')
def shell(title,body,script=''):
    return '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+html.escape(title)+'</title><style>'+CSS+'</style></head><body><main><nav><b>PROJECT ALEXANDRIA / RESEARCH NOTES</b><a href="index.html">Results &amp; methods</a><a href="examples.html">Before / after reader</a><a href="README.md">Reproduction guide</a></nav>'+body+'<footer>Measured on the same 97 papers and 970 questions. All outputs and failure cases retained. 24 October 2026.</footer></main>'+script+'</body></html>'


def diff_pair(a,b):
    aa=re.findall(r'\s+|\S+',a);bb=re.findall(r'\s+|\S+',b);left=[];right=[]
    for tag,i,j,k,l in difflib.SequenceMatcher(a=aa,b=bb,autojunk=False).get_opcodes():
        x=html.escape(''.join(aa[i:j]));y=html.escape(''.join(bb[k:l]))
        left.append(x if tag=='equal' else '<del>'+x+'</del>')
        right.append(y if tag=='equal' else '<ins>'+y+'</ins>')
    return ''.join(left),''.join(right)


def main():
    p=argparse.ArgumentParser(description=__doc__);p.add_argument('--evidence',required=True,type=Path);p.add_argument('--out',default=HERE,type=Path);args=p.parse_args()
    root=args.evidence;out=args.out;out.mkdir(parents=True,exist_ok=True)
    combined=load(root/'numbers_guarded/outputs/combined_comparison.json')['conditions']
    numeric=combined['numbers_percent_guarded'];article=combined['delete_articles_case_guard'];modifier=combined['delete_adjective_adverb_only']
    table=''
    for name,v in combined.items():
        n=v['overlap']['narrative'];m=v['meaning_counts'];count=v['reviewed_changed_windows'];bad=m.get('major_meaning_change',0)+m.get('unintelligible',0)
        quality='—' if not count else f'{bad}/{count} ({bad/count:.1%})'
        if m.get('unparsed'):quality+=f'; {m["unparsed"]} unparsed'
        classes='good' if name in ['delete_articles_case_guard','numbers_percent_guarded'] else ''
        qa=v['qa'];ci=qa['paired_difference_vs_raw_95ci_pp']
        table+=f'<tr class="{classes}"><th>{html.escape(LABELS[name])}</th><td>{n["mean_covered_fraction_six_plus"]:.2%}<br><span class="bar" style="width:{n["mean_covered_fraction_six_plus"]*1700:.1f}px"></span></td><td>{n["mean_covered_fraction_seven_plus"]:.2%}</td><td>{qa["correct"]}/970<br><span class="small">{qa["accuracy"]:.2%}</span></td><td>{quality}</td><td>{n["strict_five_word_pass"]}/97</td><td>{v["extra_cpu_core_hours_38m"]:,.0f}</td></tr>'
    nm=numeric['deletion'];nmc=numeric['meaning_counts'];nmbad=nmc.get('major_meaning_change',0)+nmc.get('unintelligible',0)
    total_cpu=article['extra_cpu_core_hours_38m']+numeric['extra_cpu_core_hours_38m']
    body=f'''<div class="eyebrow">Cheap CPU edits · frozen scientific-summary benchmark</div>
<h1>Fewer literal matches.<br>How much meaning survives?</h1>
<p class="lead">Can carefully deleting articles, or changing how a number is written, reduce copied wording without another language-model repair? We tested the saved summaries against their complete papers and checked both question answering and every newly edited sentence.</p>
<div class="cards"><div class="card"><span class="small">Protected articles + numeric notation</span><b class="big">{numeric['overlap']['narrative']['mean_covered_fraction_six_plus']:.2%}</b>mean summary-word coverage in source matches of six or more words</div><div class="card"><span class="small">Same 970 original questions</span><b class="big">{numeric['qa']['correct']}/970</b>versus 915 before these additional CPU stages</div><div class="card"><span class="small">Deployment of the new stages</span><b class="big">0 extra GPUh</b>about {total_cpu:,.0f} CPU core-hours for 38M papers; generation and the existing Gemma repair are separate</div></div>
<p class="note"><b>Literal matching is not the whole objective.</b> Writing “25%” as “twenty-five percent” can break a copied string while expressing exactly the same quantity. It is a notation change, not independent paraphrasing. Broad adjective/adverb deletion can damage science even when most multiple-choice answers remain correct.</p>
<h2>What was compared?</h2><div class="cards"><div class="card"><b>1 · Keep the existing input</b><p>The same 97 saved Gemma 12B rank-128 summaries, after one Gemma E2B repair and the frozen CPU phrase bank. No paper is regenerated or dropped.</p></div><div class="card"><b>2 · Change only a copied passage</b><p>Each candidate must lower the absolute number of copied words and their fraction. Article and modifier arms start from the common 9.04% baseline. Numeric arms start after protected article deletion.</p></div><div class="card"><b>3 · Evaluate the final text</b><p>Re-audit against the complete source. Keep every original QA slot. Independently review all newly changed sentence/window pairs with the frozen 27B teacher.</p></div></div>
<h2>All conditions, including failures</h2><div class="scroll"><table><thead><tr><th>Condition</th><th>Copied words ≥6</th><th>Copied words ≥7</th><th>QA accuracy</th><th>Major/unintelligible edited windows</th><th>Summaries entirely ≤5</th><th>Extra CPU coreh /38M</th></tr></thead><tbody>{table}</tbody></table></div>
<p class="small">CPU work is assumed to overlap existing GPU generation/repair. CPU figures measure the listed stage. Add protected-article CPU time to either numeric arm. Shared source indexes and warmed variants affect small timing differences. GPU generation + the existing one-round Gemma repair retain the earlier planning estimate of 73,699 GH200 GPUh/38M at 85% useful capacity; bulk I/O is outside these CPU measurements.</p>
<h2>How the evaluation works</h2><div class="two"><section class="panel"><h3>Question answering: can a student use the summary?</h3><p>Qwen2.5-7B-Instruct receives one summary and one of the paper’s original questions. There are ten fixed MCQs per paper, 970 in total. The question text, answer parser, gold answers, sampling settings and question-specific seeds are unchanged. Exact same contexts reuse the same answer.</p><p>QA differences of one or a few questions are uncertain on 97 papers. The modifier-only arm scored {modifier['qa']['correct']}/970; its paired 95% paper-bootstrap difference versus the pre-deletion baseline is {modifier['qa']['paired_difference_vs_raw_95ci_pp'][0]:+.2f} to {modifier['qa']['paired_difference_vs_raw_95ci_pp'][1]:+.2f} percentage points.</p></section><section class="panel"><h3>Meaning: did the edit lose a scientific qualification?</h3><p>The frozen Qwen3.8-27B FP8 teacher compares every original/edited sentence or window, with thinking disabled. Labels distinguish equivalent wording, awkward wording, minor meaning change, major meaning change and unintelligible text.</p><p>The modifier-only arm triggered {modifier['meaning_counts'].get('major_meaning_change',0)+modifier['meaning_counts'].get('unintelligible',0)} severe/unintelligible labels among {modifier['reviewed_changed_windows']} edited windows. The numeric arm triggered {nmbad}/{numeric['reviewed_changed_windows']}. These are automatic judgments, not human error rates. The reviewer undercalled removal of “randomized” and “may” in controls.</p></section></div>
<h2>What does “copied words ≥6” mean?</h2><p>For each summary, count each narrative word that belongs to at least one consecutive source match of six or more normalized whitespace words. Divide by all narrative words in that summary, then average the 97 percentages. Overlapping windows count each word position once. Evidence quotes and bibliographic metadata are audited separately. Case and punctuation are normalized; a separate punctuation-split diagnostic is retained.</p><p>An isolated six-word match becomes at most five words after one deletion: all six possible single-word deletions passed our sanity check. Other passages in the same summary can still fail. The matcher never treats a gapped subsequence as a contiguous quote.</p>
<h2>Numbers: real overlap reduction or a larger denominator?</h2><p>The protected-article input contains {nm['baseline_words']:,} narrative words, of which {nm['baseline_copied_words']:,} are covered by ≥6-word matches. After numeric formatting there are {nm['words']:,} narrative words and {nm['absolute_copied_words']:,} covered words. Word count changes by {(nm['words']/nm['baseline_words']-1):+.2%}. Coverage using the original per-paper word counts as fixed denominators is {nm['coverage_with_fixed_original_denominator']:.2%}, versus the reported {numeric['overlap']['narrative']['mean_covered_fraction_six_plus']:.2%}. The improvement is therefore not just denominator inflation.</p><p>Only supported cardinals and decimals are transformed. Decimal value, sign and decimal-place precision must round-trip exactly. Percent quantities are rewritten as complete expressions: “25%” ↔ “twenty-five percent”, avoiding malformed “twenty-five%”. Formulas, operators, LaTeX, quoted/code text, model-like identifiers and explicit figure/equation references have conservative exclusions. These heuristics are not complete named-entity recognition.</p>
<h3>Why the original numeric prototype is retained as a diagnostic</h3><p>The first numeric pass also changed technical spellings such as the DNA labels 3-prime/5-prime, a crystallographic index, and parts of mathematical notation. Preserving a Decimal value alone does not prove that a number is a quantity. The guarded arm therefore requires quantity context and leaves detected formula-containing sentences, primed values, leading-zero integers, reference IDs and crystallographic labels untouched. This sacrifices some overlap reduction. All original outputs and scores remain visible.</p><p>The automatic reviewer also misread one valid conversion, 90 → ninety, as 90 → 9. Its raw judgment is preserved and counted; this is an explicit reviewer false positive on numerical value, not a silently corrected label.</p><h2>What we would improve next, cheaply</h2><ol><li><b>Grammar-aware optional words.</b> Test removing optional “that” after specific reporting-verb frames and “of” in narrow phrases such as “all of the samples” → “all the samples”. Preserve quantifiers, negation, tense and causal connectors. These next rules are proposals, not measured gains.</li><li><b>Exact unit aliases.</b> Test “mg” ↔ “milligrams” only next to a quantity and outside formulas, with a small exact unit map. Do not use unrestricted synonyms for technical terms.</li><li><b>Paper-specific identifier protection.</b> Reuse source-declared abbreviations and a cached domain vocabulary. The original article arm deleted the molecule abbreviation “An”; the case-aware guard fixes the observed failure. Derive future rules on the 865 training papers, then freeze them for a fresh evaluation.</li><li><b>Spend model calls on the hard remainder.</b> Cache source indexes, batch POS work, and rank unresolved sentences by potential copied-word reduction. If a model is still needed, repair a small high-yield subset and retain the original on failed checks. No throughput or GPU saving is claimed for this unmeasured proposal.</li></ol>
<h2>Reproduce and inspect</h2><p><a href="examples.html">Open the before/after reader</a> for five full papers and labelled sentence examples. <a href="README.md">The reproduction guide</a> explains the portable CPU command and hash-verified saved-evidence replay. <a href="results/combined_comparison.json">Machine-readable results</a>, every original QA response, complete source-copy evidence, edit traces and the historical launch scripts are included.</p><p class="small">This is a repeatedly used exploratory benchmark. The article case/grammar guard was added after inspecting meaning failures. Future rule development needs a new held-out set; no claim of blind generalization or elimination of all literal copying is made.</p>'''
    (out/'index.html').write_text(shell('Alexandria · CPU wording repair results',body))
    rows=readlines(root/'common/cohort97.jsonl');by_doc={r['document_id']:r for r in rows}
    requested=['bethgelab-10000','arxiv-1000004','arxiv-1000013','arxiv-10024','arxiv-10019']
    ids=[d for d in requested if d in by_doc]
    for row in rows:
        if len(ids)>=5:break
        if row['document_id'] not in ids:ids.append(row['document_id'])
    records={};pairs=[]
    for run,names in RUNS.items():
        reviewdir=root/run/'outputs/reviews'
        reviewed=[x for p in sorted(reviewdir.glob('*.jsonl')) for x in readlines(p)]
        for name in names:
            records[name]={}
            for doc in ids:
                row=by_doc[doc];records[name][doc]=load(root/run/f'outputs/repaired/{name}/{row["uid"]}.json')['summary']
            for severity in ['unchanged_or_equivalent','awkward_only','minor_meaning_change','major_meaning_change','unintelligible']:
                eligible=sorted([r for r in reviewed if r['condition']==name and r['judgment']['severity']==severity],key=lambda r:r['pair_id'])
                if eligible:
                    x=eligible[0];before,after=diff_pair(x['before'],x['after'])
                    pairs.append(dict(condition=name,severity=severity,document_id=x.get('document_id',''),before=before,after=after,reason=x['judgment'].get('reason','')))
    payload=dict(labels=LABELS,records=records,pairs=pairs,papers=[dict(id=d,title=records['baseline'][d].get('title',d)) for d in ids])
    reader='''<div class="eyebrow">Read the text · inspect the failures</div><h1>Before and after</h1><p class="lead">Five complete scientific summaries, plus illustrative changed sentences from every treatment. Full summaries compare against the common pre-deletion input. Numeric arms also include protected article deletion; sentence pairs compare against each arm’s immediate input.</p><div class="filters"><div><label for="paper">Paper</label><select id="paper"></select></div><div><label for="condition">CPU edit</label><select id="condition"></select></div></div><p class="small">The five full papers are a fixed illustrative selection. Labelled snippets are selected deterministically by severity and pair hash; they are not a representative error-rate sample. All pairs are in the evidence bundles.</p><h2 id="paperTitle"></h2><div class="two"><div class="summary"><h3>Before additional CPU edits</h3><div id="before"></div></div><div class="summary"><h3 id="afterTitle"></h3><div id="after"></div></div></div><h2>Changed sentence examples</h2><div id="pairs"></div>'''
    js='''const D=JSON.parse(document.getElementById('data').textContent);const paper=document.getElementById('paper'),condition=document.getElementById('condition');for(const p of D.papers){let o=document.createElement('option');o.value=p.id;o.textContent=p.title;paper.append(o)}for(const [id,label] of Object.entries(D.labels)){if(id==='baseline')continue;let o=document.createElement('option');o.value=id;o.textContent=label;condition.append(o)}condition.value='numbers_percent';function value(v){if(typeof v==='string'){let p=document.createElement('p');p.textContent=v;return p}if(Array.isArray(v)){let ul=document.createElement('ul');for(const x of v){let li=document.createElement('li');li.append(value(x));ul.append(li)}return ul}if(v&&typeof v==='object'){let dl=document.createElement('dl');for(const [k,x]of Object.entries(v)){let dt=document.createElement('dt');dt.textContent=k;let dd=document.createElement('dd');dd.append(value(x));dl.append(dt,dd)}return dl}let p=document.createElement('p');p.textContent=String(v);return p}function summary(target,s){target.replaceChildren();for(const [k,v]of Object.entries(s)){let d=document.createElement('details'),h=document.createElement('summary');h.textContent=k.replaceAll('_',' ');d.open=k==='executive_summary';d.append(h,value(v));target.append(d)}}function update(){const id=paper.value,c=condition.value;document.getElementById('paperTitle').textContent=D.records.baseline[id].title;document.getElementById('afterTitle').textContent=D.labels[c];summary(document.getElementById('before'),D.records.baseline[id]);summary(document.getElementById('after'),D.records[c][id]);const target=document.getElementById('pairs');target.replaceChildren();for(const p of D.pairs.filter(p=>p.condition===c)){let article=document.createElement('article');article.className='pair';let h=document.createElement('h3');h.textContent=p.severity.replaceAll('_',' ')+' · '+p.document_id;let row=document.createElement('div');row.className='two';let a=document.createElement('div'),b=document.createElement('div');a.innerHTML='<b>Before</b><p>'+p.before+'</p>';b.innerHTML='<b>After</b><p>'+p.after+'</p>';row.append(a,b);let why=document.createElement('p');why.className='small';why.textContent='Automatic reviewer: '+p.reason;article.append(h,row,why);target.append(article)}}paper.onchange=update;condition.onchange=update;update();'''
    js=js.replace("condition.value='numbers_percent'","condition.value='numbers_percent_guarded'")
    script='<script type="application/json" id="data">'+dump(payload)+'</script><script>'+js+'</script>'
    (out/'examples.html').write_text(shell('Alexandria · before / after reader',reader,script))
    (out/'view_manifest.json').write_text(json.dumps(dict(papers=ids,conditions=list(LABELS),illustrative_pairs=len(pairs),all_full_summary_variants=5*len(LABELS)),indent=2)+'\n')
    print('Built index.html and examples.html:',len(pairs),'illustrative pairs,',5*len(LABELS),'full summary variants')


if __name__=='__main__':main()
